-- Cursos (el examen final va aparte, en exam_questions, que los alumnos no pueden leer)
insert into public.courses (id, slug, title, data, published, soon, featured, is_new, sort) values ('c-lean', 'lean-en-la-practica', 'Lean en la práctica', $j${"subtitle": "Eliminá desperdicios y hacé que el trabajo fluya", "cat": "procesos", "level": "Inicial", "instructors": ["andriy"], "cover": "img/covers/lean.jpg", "desc": "Un recorrido práctico por el pensamiento Lean aplicado a plantas, depósitos y oficinas. Vas a aprender a ver el desperdicio, mapear el flujo de valor y armar un plan de mejora de 90 días con resultados medibles.", "outcomes": ["Identificar los 8 desperdicios en cualquier proceso", "Construir el mapa de flujo de valor (VSM) actual y futuro", "Calcular lead time, tiempo de valor agregado y eficiencia del proceso", "Aplicar flujo continuo, sistema pull y trabajo estandarizado", "Armar un plan de implementación de 90 días con indicadores"], "forWho": "Responsables de operaciones, supervisores, analistas de procesos y mandos medios de industria, logística, salud y servicios.", "req": "No hace falta experiencia previa.", "modules": [{"id": "lean-m1", "t": "Pensar en Lean", "lessons": [{"id": "lean-1-1", "res": [], "t": "Qué es Lean (y qué no es)", "type": "video", "min": 9, "v": "ink", "sum": "Lean no es recortar personal ni una caja de herramientas: es un sistema para entregar más valor con menos esfuerzo, tiempo y recursos.", "pts": ["Nace en el Sistema de Producción Toyota", "Mira el flujo de valor completo, no cada área por separado", "Se apoya en dos pilares: mejora continua y respeto por las personas"]}, {"id": "lean-1-2", "res": [], "t": "Valor desde la mirada del cliente", "type": "video", "min": 8, "v": "drops", "sum": "Todo lo que el cliente no está dispuesto a pagar es una oportunidad de mejora.", "pts": ["Actividades que agregan valor", "Actividades necesarias sin valor agregado", "Desperdicio puro: eliminar"]}, {"id": "lean-1-3", "res": [{"n": "Planilla de relevamiento de desperdicios", "k": "xlsx", "gen": "desperdicios"}], "t": "Los 8 desperdicios", "type": "video", "min": 14, "v": "wave", "sum": "Transporte, inventario, movimiento, esperas, sobreproducción, sobreprocesamiento, defectos y talento no aprovechado: cómo reconocerlos en tu día a día.", "pts": ["Regla mnemotécnica TIMWOODS", "Ejemplos en planta y en oficina", "Cómo relevarlos en una recorrida de 30 minutos"]}, {"id": "lean-1-4", "res": [], "t": "Control del módulo 1", "type": "quiz", "min": 6, "qs": [{"q": "¿Qué parte del proceso agrega valor?", "o": ["La que transforma el producto o servicio de una forma que el cliente valora y paga", "Toda actividad que hace la empresa", "Las inspecciones de calidad", "Los traslados entre áreas"], "a": 0, "e": "Agrega valor lo que transforma el producto o servicio y el cliente está dispuesto a pagar."}, {"q": "Un informe que se prepara todas las semanas y nadie lee es…", "o": ["Sobreprocesamiento", "Transporte", "Inventario", "Valor agregado"], "a": 0, "e": "Hacer más de lo que el cliente (interno o externo) necesita es sobreprocesamiento."}, {"q": "El octavo desperdicio es…", "o": ["Talento no aprovechado", "Energía", "Papel", "Reuniones"], "a": 0, "e": "No aprovechar las ideas y capacidades de las personas es el octavo desperdicio."}]}]}, {"id": "lean-m2", "t": "Ver el flujo", "lessons": [{"id": "lean-2-1", "res": [{"n": "Plantilla de datos para el VSM", "k": "xlsx", "gen": "vsm"}], "t": "Mapa de flujo de valor paso a paso", "type": "video", "min": 16, "v": "light", "sum": "Cómo dibujar el VSM del estado actual: proceso, inventarios, flujo de información y línea de tiempo.", "pts": ["Elegir la familia de productos", "Caminar el proceso de punta a punta", "Dibujar con lápiz antes que con software"]}, {"id": "lean-2-2", "res": [], "t": "Lead time, tiempo de ciclo y valor agregado", "type": "video", "min": 11, "v": "mist", "sum": "Las tres medidas que muestran cuánto tarda de verdad tu proceso y cuánto de ese tiempo vale para el cliente.", "pts": ["Lead time: del pedido a la entrega", "Tiempo de ciclo: cada cuánto sale una unidad", "Eficiencia = valor agregado / lead time"]}, {"id": "lean-2-3", "res": [], "t": "Caso: el recorrido de un pedido", "type": "lectura", "min": 6, "body": ["Un pedido de un cliente industrial tardaba, en promedio, cinco días corridos entre que ingresaba por correo y salía del depósito. Cuando el equipo cronometró las tareas que realmente transformaban algo —cargar el pedido, preparar, controlar y embalar— sumaron apenas 40 minutos.", "El resto era espera: el correo sin leer hasta la tarde, la aprobación de crédito que se hacía una vez por día, la preparación por tandas y un control final que esperaba a que se juntaran varios pedidos.", "Con el mapa en la pared, la conversación cambió. Ya no se discutía quién trabajaba más o menos, sino dónde se frenaba el pedido. Las primeras tres mejoras no costaron nada: revisar pedidos cada dos horas, aprobar crédito en línea para clientes habituales y preparar pedido por pedido.", "Preguntas para tu proceso: ¿cuánto tarda de punta a punta? ¿Cuánto de ese tiempo alguien está agregando valor? ¿Dónde se acumula trabajo esperando?"]}]}, {"id": "lean-m3", "t": "Herramientas para fluir", "lessons": [{"id": "lean-3-1", "res": [], "t": "Flujo continuo y sistema pull", "type": "video", "min": 12, "v": "fil", "sum": "Pasar de trabajar por lotes a trabajar al ritmo de lo que el cliente consume.", "pts": ["Por qué los lotes grandes esconden problemas", "Supermercados y kanban", "Cuándo conviene y cuándo no"]}, {"id": "lean-3-2", "res": [], "t": "Trabajo estandarizado", "type": "video", "min": 10, "v": "rise", "sum": "La mejor forma conocida de hacer una tarea, escrita y visible, como base para seguir mejorando.", "pts": ["Secuencia, tiempo y stock estándar", "Hojas de instrucción que se usan", "El estándar se mejora, no se impone"]}, {"id": "lean-3-3", "res": [], "t": "Gestión visual y tableros de piso", "type": "video", "min": 9, "v": "drops", "sum": "Que cualquiera pueda saber en segundos si el proceso va bien o mal.", "pts": ["Indicadores a la vista de quien hace el trabajo", "Señales de anomalía", "Reunión diaria frente al tablero"]}]}, {"id": "lean-m4", "t": "Implementar sin perder impulso", "lessons": [{"id": "lean-4-1", "res": [{"n": "Plantilla de plan de 90 días", "k": "xlsx", "gen": "plan90"}], "t": "Plan de 90 días", "type": "video", "min": 10, "v": "ink", "sum": "Cómo priorizar, asignar responsables y medir para que la mejora no quede en un taller lindo.", "pts": ["Elegir un flujo piloto", "Metas medibles al día 30, 60 y 90", "Ritmo de seguimiento semanal"]}, {"id": "lean-4-2", "res": [], "t": "Errores comunes al implementar Lean", "type": "lectura", "min": 5, "body": ["Copiar herramientas sin entender el problema que resuelven. Un kanban mal dimensionado genera más faltantes que el sistema anterior.", "Hacerlo como proyecto del área de mejora y no de la operación. Si el supervisor no es dueño del cambio, el cambio dura lo que dura el consultor.", "Medir actividad en lugar de resultados: cantidad de talleres, de tarjetas o de carteles no dicen nada sobre el lead time o los defectos.", "Olvidarse de las personas. Lean se sostiene cuando la gente ve que sus ideas se implementan y que la mejora no se usa para recortar puestos."]}, {"id": "lean-4-3", "res": [], "t": "Sostener la mejora", "type": "video", "min": 8, "v": "wave", "sum": "Rutinas de liderazgo para que lo logrado no se pierda a los seis meses.", "pts": ["Recorridas al lugar de trabajo", "Auditorías breves y frecuentes", "Celebrar y comunicar los resultados"]}]}]}$j$::jsonb, true, false, true, false, 0) on conflict (id) do update set slug = excluded.slug, title = excluded.title, data = excluded.data, published = excluded.published, soon = excluded.soon, featured = excluded.featured, is_new = excluded.is_new, sort = excluded.sort, updated_at = now();
select public_set_exam_seed('c-lean', $j${"pass": 70, "minutes": 15, "attempts": 3}$j$::jsonb, $j$[{"q": "¿Cuál es el foco principal de Lean?", "o": ["Reducir personal", "Maximizar el valor para el cliente eliminando desperdicios", "Automatizar todos los procesos", "Aumentar el inventario de seguridad"], "a": 1, "e": "Lean busca entregar más valor con menos recursos, eliminando lo que el cliente no paga."}, {"q": "Un operario camina 40 metros varias veces por turno para buscar herramientas. ¿Qué desperdicio es?", "o": ["Transporte", "Movimiento", "Sobreproducción", "Defectos"], "a": 1, "e": "El desplazamiento innecesario de personas es movimiento; el transporte se refiere a mover materiales."}, {"q": "¿Qué desperdicio suele considerarse el peor porque genera muchos de los otros?", "o": ["Esperas", "Sobreproducción", "Sobreprocesamiento", "Talento no aprovechado"], "a": 1, "e": "Producir de más o antes de tiempo genera inventario, transporte, movimiento y esconde defectos."}, {"q": "En un mapa de flujo de valor, el lead time es…", "o": ["El tiempo que una persona tarda en hacer su tarea", "El tiempo total desde que entra el pedido hasta que se entrega", "El tiempo de valor agregado", "El tiempo de preparación de máquina"], "a": 1, "e": "El lead time mide el recorrido completo del pedido, incluidas las esperas."}, {"q": "Un proceso tiene 5 días corridos de lead time (7.200 minutos) y 40 minutos de valor agregado. Su eficiencia es aproximadamente…", "o": ["56 %", "5,6 %", "0,56 %", "0,056 %"], "a": 2, "e": "40 / 7.200 = 0,0056, es decir 0,56 %. Es un valor habitual en procesos que nunca se mapearon."}, {"q": "Un sistema pull significa que…", "o": ["Se produce según el pronóstico", "Se produce lo que el proceso siguiente consume", "Se empuja la producción para mantener ocupada a la gente", "Se compra todo por adelantado"], "a": 1, "e": "En pull, el consumo real del proceso cliente dispara la producción."}, {"q": "¿Para qué sirve el trabajo estandarizado?", "o": ["Para que nadie cambie nada nunca", "Para fijar la mejor forma conocida y tener una base sobre la cual mejorar", "Para controlar a los operarios", "Para reemplazar la capacitación"], "a": 1, "e": "Sin estándar no hay mejora: es el punto de partida que se va actualizando."}, {"q": "¿Qué indica una buena gestión visual?", "o": ["Que cualquiera entienda el estado del proceso en segundos", "Que haya muchos carteles", "Que los datos estén cargados en el sistema", "Que el supervisor reciba un informe semanal"], "a": 0, "e": "La gestión visual hace evidente lo normal y lo anormal, en el lugar y en el momento."}]$j$::jsonb);
insert into public.courses (id, slug, title, data, published, soon, featured, is_new, sort) values ('c-layout', 'layout-de-planta-slp', 'Distribución de planta con SLP', $j${"subtitle": "Diseñá el layout con método, no a ojo", "cat": "procesos", "level": "Avanzado", "instructors": ["andriy"], "cover": "img/covers/layout.jpg", "desc": "El método Systematic Layout Planning aplicado paso a paso: de los flujos y las relaciones entre áreas al plano final. Incluye el análisis de un caso real de ampliación de planta.", "outcomes": ["Relevar flujos, distancias y recorridos del layout actual", "Construir la matriz y el diagrama de relaciones entre áreas", "Calcular requerimientos de espacio", "Generar y evaluar alternativas con criterios ponderados"], "forWho": "Gerentes de planta, ingenieros de procesos, responsables de proyectos de mudanza o ampliación.", "req": "Recomendado haber hecho Lean en la práctica.", "modules": [{"id": "layout-m1", "t": "Diagnóstico del layout actual", "lessons": [{"id": "layout-1-1", "res": [], "t": "Por qué el layout define la productividad", "type": "video", "min": 8, "v": "light", "sum": "Cada metro de recorrido innecesario se paga todos los días, durante años."}, {"id": "layout-1-2", "res": [{"n": "Matriz desde-hacia", "k": "xlsx", "gen": "desdehacia"}], "t": "Relevamiento de flujos y distancias", "type": "video", "min": 13, "v": "mist", "sum": "Cómo medir lo que se mueve, cuánto y entre qué áreas."}, {"id": "layout-1-3", "res": [], "t": "Diagrama de recorrido (espagueti)", "type": "video", "min": 9, "v": "fil", "sum": "Dibujar sobre el plano el camino real de materiales y personas."}]}, {"id": "layout-m2", "t": "Método SLP", "lessons": [{"id": "layout-2-1", "res": [], "t": "Análisis producto-cantidad", "type": "video", "min": 10, "v": "wave", "sum": "Volumen y variedad definen el tipo de distribución: por producto, por proceso o celular."}, {"id": "layout-2-2", "res": [{"n": "Matriz de relaciones SLP", "k": "xlsx", "gen": "slp"}], "t": "Matriz de relaciones", "type": "video", "min": 12, "v": "ink", "sum": "Clasificar la cercanía deseada entre áreas con los códigos A, E, I, O, U y X."}, {"id": "layout-2-3", "res": [], "t": "Diagrama de relaciones entre áreas", "type": "video", "min": 11, "v": "drops", "sum": "Pasar de la matriz a un esquema espacial que respete las relaciones más fuertes."}, {"id": "layout-2-4", "res": [], "t": "Control del módulo 2", "type": "quiz", "min": 6, "qs": [{"q": "En SLP, la relación «A» significa…", "o": ["Absolutamente necesaria", "Aceptable", "Ausente", "Alternativa"], "a": 0, "e": "A = absolutamente necesaria la cercanía."}, {"q": "El diagrama de relaciones…", "o": ["Representa las áreas y la intensidad de sus vínculos", "Es un organigrama", "Es el plano de arquitectura final", "Es un cronograma"], "a": 0, "e": "Es un esquema espacial previo al plano, guiado por las relaciones."}, {"q": "El análisis P-Q ordena…", "o": ["Los productos según la cantidad producida", "Los proveedores por precio", "Las personas por antigüedad", "Los pedidos por cliente"], "a": 0, "e": "P-Q = producto-cantidad."}]}]}, {"id": "layout-m3", "t": "Del diagrama al plano", "lessons": [{"id": "layout-3-1", "res": [], "t": "Requerimientos de espacio", "type": "video", "min": 9, "v": "rise", "sum": "Equipos, operarios, materiales, pasillos y crecimiento previsto."}, {"id": "layout-3-2", "res": [], "t": "Alternativas y evaluación ponderada", "type": "video", "min": 10, "v": "light", "sum": "Comparar opciones con criterios explícitos: flujo, seguridad, flexibilidad y costo."}, {"id": "layout-3-3", "res": [], "t": "Caso real: de 760 m² a 1.860 m²", "type": "lectura", "min": 7, "body": ["Una planta que crecía sin orden decidió mudarse de 760 m² a una nave de 1.860 m². El riesgo era repetir los mismos cruces y recorridos, ahora con más metros.", "El trabajo empezó por los datos: qué se movía, cuánto y entre qué áreas. Con la matriz desde-hacia y la matriz de relaciones se identificaron las cercanías críticas y las incompatibles (por ejemplo, zonas limpias lejos de procesos con polvo).", "Se generaron tres alternativas y se evaluaron con el equipo usando criterios ponderados. La elegida no era la más barata, pero era la que mejor ordenaba el flujo y dejaba espacio para crecer sin volver a mudarse.", "La lección: el layout no se resuelve con un plano lindo, se resuelve con flujos medidos y decisiones explícitas."]}]}]}$j$::jsonb, true, false, false, true, 1) on conflict (id) do update set slug = excluded.slug, title = excluded.title, data = excluded.data, published = excluded.published, soon = excluded.soon, featured = excluded.featured, is_new = excluded.is_new, sort = excluded.sort, updated_at = now();
select public_set_exam_seed('c-layout', $j${"pass": 70, "minutes": 12, "attempts": 3}$j$::jsonb, $j$[{"q": "¿Qué significa SLP?", "o": ["Systematic Layout Planning", "Standard Lean Process", "Strategic Logistics Plan", "Simple Location Plan"], "a": 0, "e": "Es el método de planificación sistemática de la distribución, de Richard Muther."}, {"q": "La matriz de relaciones clasifica la cercanía entre áreas con…", "o": ["Las letras A, E, I, O, U y X", "Números del 1 al 10", "Alta, media y baja", "Verde, amarillo y rojo"], "a": 0, "e": "A, E, I, O, U, X: de absolutamente necesaria a no deseable."}, {"q": "Una relación «X» significa…", "o": ["Cercanía absolutamente necesaria", "Cercanía no deseable", "Importante", "Sin importancia"], "a": 1, "e": "X indica que las áreas deben quedar separadas."}, {"q": "El análisis producto-cantidad ayuda a…", "o": ["Elegir el tipo de distribución según volumen y variedad", "Calcular salarios", "Definir precios", "Elegir proveedores"], "a": 0, "e": "Alto volumen y poca variedad suelen ir a distribución por producto; lo contrario, por proceso."}, {"q": "¿Qué herramienta muestra el recorrido real de materiales y personas sobre el plano?", "o": ["Diagrama de recorrido (espagueti)", "Organigrama", "Diagrama de Gantt", "Balance general"], "a": 0, "e": "El espagueti hace visibles los cruces y las distancias."}, {"q": "Al evaluar alternativas de layout conviene…", "o": ["Elegir la más barata", "Compararlas con criterios ponderados (flujo, seguridad, flexibilidad, costo)", "Elegir la que más le guste a la gerencia", "Copiar el layout de otra planta"], "a": 1, "e": "Los criterios ponderados hacen explícita y defendible la decisión."}]$j$::jsonb);
insert into public.courses (id, slug, title, data, published, soon, featured, is_new, sort) values ('c-logistica', 'almacenes-y-logistica-interna', 'Almacenes y logística interna', $j${"subtitle": "Ordená el depósito, acortá recorridos y confiá en tu inventario", "cat": "procesos", "level": "Intermedio", "instructors": ["andriy"], "cover": "img/covers/logistica.jpg", "desc": "Cómo convertir el depósito en un proceso que fluye: indicadores, ubicación por rotación, señalización y conteos cíclicos para tener un inventario confiable.", "outcomes": ["Medir el desempeño del depósito con pocos indicadores", "Ubicar productos según su rotación (ABC y slotting)", "Implementar conteos cíclicos", "Encontrar las causas de las diferencias de inventario"], "forWho": "Jefes de depósito, responsables de logística y abastecimiento.", "req": "Ninguno.", "modules": [{"id": "logistica-m1", "t": "El depósito como proceso", "lessons": [{"id": "logistica-1-1", "res": [], "t": "Flujos de entrada y salida", "type": "video", "min": 9, "v": "fil", "sum": "Recepción, almacenamiento, preparación y despacho como un único flujo."}, {"id": "logistica-1-2", "res": [], "t": "Indicadores del depósito", "type": "video", "min": 10, "v": "light", "sum": "Precisión de inventario, pedidos perfectos, productividad de preparación y ocupación."}]}, {"id": "logistica-m2", "t": "Ubicación y slotting", "lessons": [{"id": "logistica-2-1", "res": [], "t": "Clasificación ABC", "type": "video", "min": 8, "v": "wave", "sum": "Los pocos ítems que concentran la mayor parte del movimiento."}, {"id": "logistica-2-2", "res": [], "t": "Slotting por rotación", "type": "video", "min": 11, "v": "drops", "sum": "Lo que más se mueve, más cerca y a mejor altura."}, {"id": "logistica-2-3", "res": [], "t": "Señalización y direccionamiento", "type": "video", "min": 7, "v": "ink", "sum": "Un código de ubicación que cualquiera entienda el primer día."}]}, {"id": "logistica-m3", "t": "Inventario confiable", "lessons": [{"id": "logistica-3-1", "res": [], "t": "Conteo cíclico", "type": "video", "min": 9, "v": "mist", "sum": "Contar un poco todos los días en lugar de cerrar el depósito una vez por año."}, {"id": "logistica-3-2", "res": [], "t": "Diferencias de inventario y sus causas", "type": "video", "min": 10, "v": "rise", "sum": "De corregir el número a corregir el proceso que generó la diferencia."}]}]}$j$::jsonb, true, false, false, false, 2) on conflict (id) do update set slug = excluded.slug, title = excluded.title, data = excluded.data, published = excluded.published, soon = excluded.soon, featured = excluded.featured, is_new = excluded.is_new, sort = excluded.sort, updated_at = now();
select public_set_exam_seed('c-logistica', $j${"pass": 70, "minutes": 10, "attempts": 3}$j$::jsonb, $j$[{"q": "En una clasificación ABC, los ítems A son…", "o": ["Los de menor valor", "Los pocos que concentran la mayor parte del movimiento o del valor", "Los obsoletos", "Los que están en la estantería A"], "a": 1, "e": "Principio de Pareto: pocos ítems explican la mayor parte."}, {"q": "El slotting es…", "o": ["Asignar ubicaciones según rotación y características del producto", "Contar inventario", "Comprar estanterías", "Despachar pedidos"], "a": 0, "e": "Ubicar bien reduce recorridos y errores de preparación."}, {"q": "Los productos de mayor rotación conviene ubicarlos…", "o": ["En el fondo del depósito", "Cerca de la zona de preparación y a altura cómoda", "En altura", "Mezclados al azar"], "a": 1, "e": "Menos recorrido y menos esfuerzo en lo que más se mueve."}, {"q": "El conteo cíclico consiste en…", "o": ["Contar todo el inventario una vez por año", "Contar periódicamente una parte del inventario según criterios", "Contar solo lo que falta", "No contar y confiar en el sistema"], "a": 1, "e": "Permite detectar y corregir causas sin frenar la operación."}, {"q": "Un indicador clave de precisión de inventario es…", "o": ["El % de ítems o ubicaciones donde el físico coincide con el sistema", "La cantidad de empleados", "Los metros cuadrados", "La cantidad de estanterías"], "a": 0, "e": "Mide cuánto podés confiar en lo que dice el sistema."}]$j$::jsonb);
insert into public.courses (id, slug, title, data, published, soon, featured, is_new, sort) values ('c-5s', '5s-el-orden-que-se-sostiene', '5S: el orden que se sostiene', $j${"subtitle": "La base de cualquier mejora, bien hecha", "cat": "mejora", "level": "Inicial", "instructors": ["andriy"], "cover": "img/covers/5s.jpg", "desc": "Las 5S explicadas para que no sean una jornada de limpieza más: clasificar, ordenar, limpiar e inspeccionar, estandarizar y sostener, con auditorías simples que mantienen el resultado.", "outcomes": ["Aplicar cada una de las 5S en planta y en oficina", "Usar tarjetas rojas para decidir qué se queda", "Diseñar estándares visuales", "Auditar y sostener el resultado"], "forWho": "Equipos operativos, supervisores y cualquier área que quiera trabajar más ordenada.", "req": "Ninguno.", "modules": [{"id": "5s-m1", "t": "Fundamentos", "lessons": [{"id": "5s-1-1", "res": [], "t": "Por qué 5S es la base de todo", "type": "video", "min": 7, "v": "drops", "sum": "Sin orden no hay estándar, y sin estándar no hay mejora."}, {"id": "5s-1-2", "res": [], "t": "Las cinco S en una mirada", "type": "video", "min": 8, "v": "ink", "sum": "Seiri, Seiton, Seiso, Seiketsu y Shitsuke, explicadas con ejemplos."}]}, {"id": "5s-m2", "t": "Implementación", "lessons": [{"id": "5s-2-1", "res": [], "t": "Seiri: clasificar", "type": "video", "min": 9, "v": "wave", "sum": "Separar lo necesario de lo innecesario con tarjetas rojas."}, {"id": "5s-2-2", "res": [], "t": "Seiton: ordenar", "type": "video", "min": 9, "v": "light", "sum": "Un lugar para cada cosa, según frecuencia de uso."}, {"id": "5s-2-3", "res": [], "t": "Seiso: limpiar e inspeccionar", "type": "video", "min": 7, "v": "mist", "sum": "Limpiar es inspeccionar: la suciedad esconde fallas."}, {"id": "5s-2-4", "res": [], "t": "Seiketsu: estandarizar", "type": "video", "min": 8, "v": "fil", "sum": "Fotos, marcas y estándares visuales para que lo logrado no dependa de la memoria."}, {"id": "5s-2-5", "res": [], "t": "Shitsuke: sostener", "type": "video", "min": 8, "v": "rise", "sum": "Hábitos, rutinas de liderazgo y reconocimiento."}]}, {"id": "5s-m3", "t": "Auditar y sostener", "lessons": [{"id": "5s-3-1", "res": [{"n": "Checklist de auditoría 5S", "k": "xlsx", "gen": "auditoria5s"}], "t": "Auditorías 5S", "type": "video", "min": 9, "v": "drops", "sum": "Una auditoría corta y frecuente vale más que una grande una vez por año."}, {"id": "5s-3-2", "res": [], "t": "5S en oficinas y espacios digitales", "type": "video", "min": 7, "v": "ink", "sum": "Carpetas compartidas, escritorios y bandejas de entrada también se ordenan."}]}]}$j$::jsonb, true, false, false, false, 3) on conflict (id) do update set slug = excluded.slug, title = excluded.title, data = excluded.data, published = excluded.published, soon = excluded.soon, featured = excluded.featured, is_new = excluded.is_new, sort = excluded.sort, updated_at = now();
select public_set_exam_seed('c-5s', $j${"pass": 70, "minutes": 10, "attempts": 3}$j$::jsonb, $j$[{"q": "¿Qué busca Seiri (clasificar)?", "o": ["Separar lo necesario de lo innecesario y retirar lo que no se usa", "Limpiar a fondo", "Pintar el piso", "Hacer auditorías"], "a": 0, "e": "Es el primer paso: sacar lo que sobra."}, {"q": "«Un lugar para cada cosa y cada cosa en su lugar» corresponde a…", "o": ["Seiton (ordenar)", "Seiso", "Seiketsu", "Shitsuke"], "a": 0, "e": "Seiton define ubicaciones claras según el uso."}, {"q": "Seiso no es solo limpiar, también es…", "o": ["Inspeccionar y detectar anomalías", "Tirar todo", "Comprar insumos", "Cambiar el layout"], "a": 0, "e": "Al limpiar se detectan pérdidas, fisuras, desgastes."}, {"q": "¿Qué S convierte las tres primeras en estándar?", "o": ["Seiketsu", "Seiri", "Seiton", "Shitsuke"], "a": 0, "e": "Seiketsu = estandarizar."}, {"q": "¿Por qué fracasan muchas implementaciones de 5S?", "o": ["Porque se hacen como jornada de limpieza y no se sostienen con estándares y auditorías", "Porque son caras", "Porque requieren software", "Porque solo sirven en Japón"], "a": 0, "e": "Sin estándar y seguimiento, el orden se pierde en semanas."}, {"q": "La tarjeta roja se usa para…", "o": ["Marcar elementos dudosos o innecesarios para decidir su destino", "Sancionar a operarios", "Señalizar matafuegos", "Identificar productos defectuosos"], "a": 0, "e": "Es una herramienta de Seiri."}]$j$::jsonb);
insert into public.courses (id, slug, title, data, published, soon, featured, is_new, sort) values ('c-kaizen', 'kaizen-con-tu-equipo', 'Kaizen con tu equipo', $j${"subtitle": "Resolver problemas de raíz, en pequeños pasos", "cat": "mejora", "level": "Intermedio", "instructors": ["andriy", "christian"], "cover": "img/covers/kaizen.jpg", "desc": "Procesos y personas en un mismo curso: el método para resolver problemas de raíz (PDCA, 5 porqués, Ishikawa, A3) y la facilitación para que el equipo se apropie de la mejora.", "outcomes": ["Plantear problemas con datos", "Encontrar causas raíz con 5 porqués e Ishikawa", "Documentar la mejora en un A3", "Preparar y facilitar un evento Kaizen"], "forWho": "Líderes de equipo, supervisores y facilitadores de mejora continua.", "req": "Recomendado haber hecho 5S o Lean en la práctica.", "modules": [{"id": "kaizen-m1", "t": "Mentalidad Kaizen", "lessons": [{"id": "kaizen-1-1", "res": [], "t": "Mejora continua: pequeños pasos", "type": "video", "min": 8, "v": "rise", "sum": "Muchas mejoras chicas, todos los días, por las personas que hacen el trabajo."}, {"id": "kaizen-1-2", "res": [], "t": "El ciclo PDCA", "type": "video", "min": 10, "v": "wave", "sum": "Planificar, hacer, verificar y actuar: la columna vertebral de toda mejora."}]}, {"id": "kaizen-m2", "t": "Resolver problemas de raíz", "lessons": [{"id": "kaizen-2-1", "res": [], "t": "Definir bien el problema", "type": "video", "min": 9, "v": "light", "sum": "Un problema bien planteado es la mitad de la solución."}, {"id": "kaizen-2-2", "res": [], "t": "5 porqués e Ishikawa", "type": "video", "min": 12, "v": "ink", "sum": "Dos herramientas simples para no quedarse en el síntoma."}, {"id": "kaizen-2-3", "res": [{"n": "Plantilla A3", "k": "doc", "gen": "a3"}], "t": "El reporte A3", "type": "video", "min": 11, "v": "fil", "sum": "Toda la historia de la mejora en una sola hoja."}]}, {"id": "kaizen-m3", "t": "El evento Kaizen", "lessons": [{"id": "kaizen-3-1", "res": [], "t": "Preparar un evento Kaizen", "type": "video", "min": 9, "v": "mist", "sum": "Alcance, datos, equipo y logística antes del primer día."}, {"id": "kaizen-3-2", "res": [], "t": "Facilitar al equipo", "type": "video", "min": 11, "v": "drops", "sum": "El rol del facilitador: preguntar, ordenar y sostener la energía del grupo.", "instructor": "christian"}, {"id": "kaizen-3-3", "res": [], "t": "Seguimiento de acciones", "type": "video", "min": 7, "v": "rise", "sum": "El evento termina; las acciones recién empiezan."}]}]}$j$::jsonb, true, false, false, false, 4) on conflict (id) do update set slug = excluded.slug, title = excluded.title, data = excluded.data, published = excluded.published, soon = excluded.soon, featured = excluded.featured, is_new = excluded.is_new, sort = excluded.sort, updated_at = now();
select public_set_exam_seed('c-kaizen', $j${"pass": 70, "minutes": 12, "attempts": 3}$j$::jsonb, $j$[{"q": "Kaizen significa…", "o": ["Cambio para mejor, mejora continua", "Calidad total", "Trabajo en equipo", "Reducción de costos"], "a": 0, "e": "Kai = cambio, zen = bueno."}, {"q": "El ciclo PDCA es…", "o": ["Planificar, Hacer, Verificar, Actuar", "Proponer, Decidir, Controlar, Archivar", "Planear, Delegar, Cobrar, Analizar", "Producir, Distribuir, Comprar, Almacenar"], "a": 0, "e": "Plan-Do-Check-Act."}, {"q": "Los 5 porqués sirven para…", "o": ["Encontrar la causa raíz de un problema", "Asignar culpables", "Hacer una encuesta", "Priorizar proyectos"], "a": 0, "e": "Preguntar «¿por qué?» sucesivamente hasta llegar a la causa."}, {"q": "El diagrama de Ishikawa organiza causas en categorías como…", "o": ["Método, mano de obra, máquina, material, medición y medio ambiente", "Ventas, marketing y finanzas", "Norte, sur, este y oeste", "Alta, media y baja"], "a": 0, "e": "Las 6M."}, {"q": "Un reporte A3 se caracteriza por…", "o": ["Contar en una sola hoja el problema, el análisis, las contramedidas y el seguimiento", "Tener 30 páginas", "Ser solo para la gerencia", "No tener datos"], "a": 0, "e": "Síntesis y lógica en una hoja."}, {"q": "En un evento Kaizen, el rol del facilitador es…", "o": ["Guiar al equipo para que encuentre y ejecute las mejoras", "Hacer las mejoras solo", "Evaluar a cada participante", "Decidir sin consultar"], "a": 0, "e": "El equipo es dueño de la mejora."}]$j$::jsonb);
insert into public.courses (id, slug, title, data, published, soon, featured, is_new, sort) values ('c-liderazgo', 'liderazgo-aumentado', 'Liderazgo aumentado', $j${"subtitle": "Liderá personas y procesos en tiempos de cambio e inteligencia artificial", "cat": "liderazgo", "level": "Intermedio", "instructors": ["christian", "andriy"], "cover": "img/covers/liderazgo.jpg", "desc": "Un programa para directivos y mandos medios que necesitan liderar equipos, sostener resultados y aprovechar la inteligencia artificial sin perder lo humano. Combina la mirada de personas y la de procesos.", "outcomes": ["Pasar de controlar tareas a desarrollar personas", "Dar feedback que se pueda usar", "Sostener reuniones 1 a 1 y acuerdos claros", "Delegar con seguimiento", "Usar la IA como copiloto sin delegar el criterio"], "forWho": "Directivos, gerentes y mandos medios con equipos a cargo.", "req": "Tener personas a cargo (o estar por tenerlas).", "modules": [{"id": "liderazgo-m1", "t": "El líder que hace falta hoy", "lessons": [{"id": "liderazgo-1-1", "res": [], "t": "Del jefe al líder", "type": "video", "min": 10, "v": "mist", "sum": "Por qué el control ya no alcanza y qué esperan hoy los equipos de quien los lidera.", "pts": ["Autoridad formal vs. influencia", "Del «qué hacer» al «para qué»", "El líder como desarrollador de personas"]}, {"id": "liderazgo-1-2", "res": [], "t": "Tu estilo de liderazgo", "type": "video", "min": 9, "v": "drops", "sum": "Reconocer tu estilo predominante y cuándo te conviene cambiarlo.", "pts": ["Directivo, persuasivo, participativo, delegativo", "Adaptar el estilo a la madurez de cada persona", "Señales de que tu estilo no funciona"]}, {"id": "liderazgo-1-3", "res": [], "t": "Control del módulo 1", "type": "quiz", "min": 6, "qs": [{"q": "¿Qué caracteriza a un líder frente a un jefe?", "o": ["Genera compromiso y desarrolla a su equipo", "Tiene un cargo más alto", "Trabaja más horas", "Toma todas las decisiones solo"], "a": 0, "e": "El liderazgo se apoya en la influencia, no solo en la autoridad."}, {"q": "Con una persona nueva y sin experiencia en la tarea conviene un estilo…", "o": ["Más directivo, con instrucciones claras y seguimiento cercano", "Totalmente delegativo", "Ausente", "Siempre el mismo para todos"], "a": 0, "e": "El estilo se adapta a la madurez de la persona en esa tarea."}, {"q": "Una señal de que tu estilo no está funcionando es…", "o": ["Que todas las decisiones y consultas pasen por vos", "Que el equipo proponga mejoras", "Que se cumplan los acuerdos", "Que la gente pida feedback"], "a": 0, "e": "Si todo pasa por el líder, el equipo no está creciendo."}]}]}, {"id": "liderazgo-m2", "t": "Conversaciones que mueven", "lessons": [{"id": "liderazgo-2-1", "res": [], "t": "Escucha activa", "type": "video", "min": 8, "v": "ink", "sum": "Escuchar para entender, no para responder.", "pts": ["Parafrasear", "Preguntar antes de opinar", "Registrar emociones, no solo datos"]}, {"id": "liderazgo-2-2", "res": [{"n": "Guía de conversación de feedback", "k": "doc", "gen": "feedback"}], "t": "Feedback que se puede usar", "type": "video", "min": 12, "v": "wave", "sum": "Un modelo simple para conversaciones sobre desempeño: situación, conducta, impacto y acuerdo."}, {"id": "liderazgo-2-3", "res": [{"n": "Guía de reunión 1 a 1", "k": "doc", "gen": "unoauno"}], "t": "Reuniones 1 a 1", "type": "video", "min": 9, "v": "light", "sum": "El espacio más rentable del calendario de un líder."}]}, {"id": "liderazgo-m3", "t": "Liderar equipos y procesos", "lessons": [{"id": "liderazgo-3-1", "res": [], "t": "Objetivos claros y acuerdos", "type": "video", "min": 10, "v": "rise", "sum": "De las expectativas implícitas a los acuerdos explícitos."}, {"id": "liderazgo-3-2", "res": [], "t": "Delegar sin desentenderse", "type": "video", "min": 9, "v": "fil", "sum": "Resultado esperado, nivel de autonomía, recursos y momentos de control."}, {"id": "liderazgo-3-3", "res": [], "t": "Liderar con indicadores", "type": "video", "min": 11, "v": "drops", "sum": "Pocos números, a la vista, revisados con el equipo.", "instructor": "andriy"}]}, {"id": "liderazgo-m4", "t": "Liderazgo aumentado con IA", "lessons": [{"id": "liderazgo-4-1", "res": [], "t": "La IA como copiloto del líder", "type": "video", "min": 12, "v": "ink", "sum": "Preparar reuniones, sintetizar información y redactar mejor, sin delegar el criterio.", "instructor": "andriy"}, {"id": "liderazgo-4-2", "res": [], "t": "Decisiones con criterio humano", "type": "video", "min": 8, "v": "mist", "sum": "Lo que la IA no puede hacer por vos: contexto, ética y vínculo."}, {"id": "liderazgo-4-3", "res": [], "t": "Tu plan de desarrollo", "type": "lectura", "min": 6, "body": ["Cerrá el programa con un plan concreto. Elegí dos conductas de liderazgo que quieras fortalecer en los próximos 90 días: por ejemplo, sostener reuniones 1 a 1 quincenales o dar feedback dentro de las 48 horas.", "Para cada conducta definí: qué vas a hacer distinto, con quién, cómo vas a saber que lo estás logrando y quién te va a dar una devolución honesta.", "Sumá un uso concreto de inteligencia artificial que te ahorre tiempo (preparar la agenda de tus reuniones, resumir informes) y medí cuánto tiempo recuperás por semana.", "Agendá hoy la primera revisión, dentro de 30 días. Un plan sin fecha de revisión es solo una buena intención."]}]}]}$j$::jsonb, true, false, true, false, 5) on conflict (id) do update set slug = excluded.slug, title = excluded.title, data = excluded.data, published = excluded.published, soon = excluded.soon, featured = excluded.featured, is_new = excluded.is_new, sort = excluded.sort, updated_at = now();
select public_set_exam_seed('c-liderazgo', $j${"pass": 70, "minutes": 15, "attempts": 3}$j$::jsonb, $j$[{"q": "La principal diferencia entre jefe y líder es que el líder…", "o": ["Genera compromiso y desarrolla a su equipo, no solo controla tareas", "Tiene un cargo más alto", "Trabaja más horas", "No tiene que rendir cuentas"], "a": 0, "e": "El liderazgo se mide por lo que el equipo logra y aprende."}, {"q": "La escucha activa implica…", "o": ["Escuchar para entender, parafrasear y preguntar antes de responder", "Esperar el turno para hablar", "Dar consejos rápido", "Anotar todo sin mirar a la persona"], "a": 0, "e": "Escuchar para comprender, no para contestar."}, {"q": "Un feedback útil es…", "o": ["Específico, sobre conductas observables y orientado a mejorar", "General y sobre la personalidad", "Solo negativo", "Solo una vez al año"], "a": 0, "e": "Conducta concreta + impacto + acuerdo."}, {"q": "La reunión 1 a 1 es principalmente…", "o": ["Un espacio del colaborador para hablar de su trabajo, sus bloqueos y su desarrollo", "Un control de tareas", "Una evaluación de desempeño", "Una reunión de equipo"], "a": 0, "e": "La agenda es, sobre todo, del colaborador."}, {"q": "Delegar bien implica…", "o": ["Acordar resultado, autonomía, recursos y momentos de seguimiento", "Pasar la tarea y desentenderse", "Hacerlo uno mismo para que salga bien", "Delegar solo lo que nadie quiere hacer"], "a": 0, "e": "Delegar no es abandonar."}, {"q": "Un objetivo bien planteado es…", "o": ["Específico, medible, alcanzable, relevante y con plazo", "Lo más ambicioso posible y sin plazo", "Definido solo por el líder sin conversarlo", "Confidencial"], "a": 0, "e": "Criterio SMART."}, {"q": "Usar la IA como copiloto del líder significa…", "o": ["Apoyarse en ella para preparar, analizar y redactar, manteniendo el criterio y la decisión humana", "Que la IA decida por el equipo", "Reemplazar las conversaciones con el equipo", "No revisar lo que produce"], "a": 0, "e": "La IA amplía, el líder decide."}, {"q": "Un plan de desarrollo personal debería incluir…", "o": ["Objetivos de crecimiento, acciones concretas, apoyos y fechas de revisión", "Solo cursos a realizar", "Una lista de defectos", "Nada por escrito"], "a": 0, "e": "Sin fecha de revisión, el plan no se cumple."}]$j$::jsonb);
