insert into public.courses (id, slug, title, data, published, soon, featured, is_new, sort) values ('c-ia', 'ia-aplicada-a-la-gestion', 'Inteligencia artificial aplicada a la gestión', $j${"subtitle": "Usá la IA para trabajar mejor, con criterio y sin riesgos", "cat": "ia", "level": "Inicial", "instructors": ["andriy"], "cover": "img/covers/ia.jpg", "desc": "Qué puede y qué no puede hacer hoy la inteligencia artificial generativa en una empresa, cómo pedirle bien las cosas y cómo llevarla a tu área con un piloto medible y una política de uso responsable.", "outcomes": ["Entender cómo funciona la IA generativa y sus límites", "Escribir pedidos (prompts) claros y efectivos", "Aplicarla a resumir, redactar, analizar y automatizar", "Diseñar un piloto de 30 días con resultados medibles"], "forWho": "Cualquier persona de la empresa, sin conocimientos técnicos.", "req": "Ninguno.", "modules": [{"id": "ia-m1", "t": "Entender la IA generativa", "lessons": [{"id": "ia-1-1", "res": [], "t": "Qué es y qué no es", "type": "video", "min": 9, "v": "fil", "sum": "Modelos que generan contenido a partir de patrones: potentes, pero no infalibles."}, {"id": "ia-1-2", "res": [], "t": "Límites y riesgos", "type": "video", "min": 8, "v": "mist", "sum": "Alucinaciones, sesgos y datos confidenciales."}]}, {"id": "ia-m2", "t": "Trabajar con IA", "lessons": [{"id": "ia-2-1", "res": [{"n": "Biblioteca de pedidos para gestión", "k": "doc", "gen": "prompts"}], "t": "Escribir buenos pedidos", "type": "video", "min": 12, "v": "light", "sum": "Contexto, tarea, formato y criterios."}, {"id": "ia-2-2", "res": [], "t": "Resumir, redactar y analizar", "type": "video", "min": 10, "v": "wave", "sum": "Los tres usos que más tiempo ahorran."}, {"id": "ia-2-3", "res": [], "t": "Automatizar tareas repetitivas", "type": "video", "min": 11, "v": "drops", "sum": "Del pedido suelto al flujo de trabajo."}]}, {"id": "ia-m3", "t": "Llevarla a la empresa", "lessons": [{"id": "ia-3-1", "res": [], "t": "Casos de uso por área", "type": "video", "min": 10, "v": "ink", "sum": "Operaciones, comercial, administración y recursos humanos."}, {"id": "ia-3-2", "res": [], "t": "Política de uso responsable", "type": "lectura", "min": 5, "body": ["Antes de que cada persona use la herramienta que encontró, conviene acordar reglas simples. La primera: no cargar datos personales ni información confidencial de la empresa o de clientes en herramientas que no estén aprobadas.", "La segunda: todo lo que produce la IA se revisa. La responsabilidad sobre un correo, un informe o una decisión sigue siendo de la persona que lo firma.", "La tercera: transparencia. Si un documento se armó con ayuda de IA y eso es relevante para quien lo recibe, se dice.", "Una política de una página, conocida por todos, vale más que un reglamento largo que nadie lee."]}, {"id": "ia-3-3", "res": [], "t": "Plan piloto de 30 días", "type": "video", "min": 9, "v": "rise", "sum": "Elegir una tarea, medir la línea de base y decidir con datos."}]}]}$j$::jsonb, true, false, true, true, 9) on conflict (id) do update set slug = excluded.slug, title = excluded.title, data = excluded.data, published = excluded.published, soon = excluded.soon, featured = excluded.featured, is_new = excluded.is_new, sort = excluded.sort, updated_at = now();
select public_set_exam_seed('c-ia', $j${"pass": 70, "minutes": 12, "attempts": 3}$j$::jsonb, $j$[{"q": "La IA generativa…", "o": ["Produce texto, imágenes u otros contenidos a partir de patrones aprendidos de datos", "Siempre dice la verdad", "Piensa como una persona", "Solo sirve para programar"], "a": 0, "e": "Genera contenido plausible, que hay que verificar."}, {"q": "Una «alucinación» de la IA es…", "o": ["Una respuesta que suena convincente pero es falsa o inventada", "Un error de conexión", "Una imagen borrosa", "Un virus"], "a": 0, "e": "Por eso todo lo generado se revisa."}, {"q": "Un buen pedido (prompt) incluye…", "o": ["Contexto, tarea concreta, formato esperado y criterios", "Una sola palabra", "Datos confidenciales de clientes", "Nada en particular"], "a": 0, "e": "Cuanto más claro el pedido, mejor la respuesta."}, {"q": "¿Qué NO deberías cargar en una herramienta de IA pública sin autorización?", "o": ["Datos personales o confidenciales de la empresa y de clientes", "Un texto propio para corregir la ortografía", "Una pregunta general", "Un borrador de correo sin datos sensibles"], "a": 0, "e": "Proteger la información es la primera regla."}, {"q": "Un buen primer caso de uso de IA en una empresa es…", "o": ["Una tarea repetitiva, frecuente y fácil de verificar", "Una decisión crítica sin supervisión", "Reemplazar a un área completa", "Algo que nadie entiende"], "a": 0, "e": "Bajo riesgo, alto volumen, fácil de medir."}, {"q": "Un piloto de IA de 30 días debería terminar con…", "o": ["Resultados medidos contra la situación inicial y la decisión de escalar o no", "La compra de licencias para todos", "Un informe sin datos", "Nada concreto"], "a": 0, "e": "Medir antes y después."}]$j$::jsonb);
insert into public.courses (id, slug, title, data, published, soon, featured, is_new, sort) values ('c-kpi', 'indicadores-y-tableros', 'Indicadores y tableros para decidir', $j${"subtitle": "Medí lo que importa y convertí datos en decisiones", "cat": "datos", "level": "Intermedio", "instructors": ["andriy"], "cover": "img/covers/indicadores.jpg", "desc": "De los objetivos a los indicadores, de los indicadores a un tablero que se lee en segundos, y del tablero a reuniones de seguimiento que terminan en acciones.", "outcomes": ["Definir indicadores ligados a objetivos y decisiones", "Completar la ficha técnica de cada KPI", "Diseñar tableros claros", "Distinguir señal de ruido y conducir reuniones de seguimiento"], "forWho": "Mandos medios, analistas y responsables de área.", "req": "Manejo básico de planillas de cálculo.", "modules": [{"id": "kpi-m1", "t": "Medir lo que importa", "lessons": [{"id": "kpi-1-1", "res": [], "t": "De objetivos a indicadores", "type": "video", "min": 9, "v": "light", "sum": "Cada indicador responde a una pregunta y alimenta una decisión."}, {"id": "kpi-1-2", "res": [{"n": "Ficha técnica de indicador", "k": "xlsx", "gen": "kpi"}], "t": "La ficha técnica de un KPI", "type": "video", "min": 10, "v": "ink", "sum": "Definición, fórmula, fuente, frecuencia, responsable y meta."}]}, {"id": "kpi-m2", "t": "Tableros", "lessons": [{"id": "kpi-2-1", "res": [], "t": "Un tablero que se lee en 10 segundos", "type": "video", "min": 12, "v": "wave", "sum": "Pocos indicadores, con meta, tendencia y semáforo claro."}, {"id": "kpi-2-2", "res": [], "t": "Tableros de piso y de gestión", "type": "video", "min": 9, "v": "fil", "sum": "Cada nivel mira lo que puede cambiar."}]}, {"id": "kpi-m3", "t": "Decidir con datos", "lessons": [{"id": "kpi-3-1", "res": [], "t": "Variación: señal o ruido", "type": "video", "min": 11, "v": "mist", "sum": "No reaccionar a cada subida o bajada."}, {"id": "kpi-3-2", "res": [], "t": "Reuniones de seguimiento con datos", "type": "video", "min": 8, "v": "drops", "sum": "Indicador, desvío, causa, acción, responsable."}]}]}$j$::jsonb, true, false, false, false, 10) on conflict (id) do update set slug = excluded.slug, title = excluded.title, data = excluded.data, published = excluded.published, soon = excluded.soon, featured = excluded.featured, is_new = excluded.is_new, sort = excluded.sort, updated_at = now();
select public_set_exam_seed('c-kpi', $j${"pass": 70, "minutes": 12, "attempts": 3}$j$::jsonb, $j$[{"q": "Un buen indicador debe estar ligado a…", "o": ["Un objetivo y a una decisión que se va a tomar con él", "Lo que es fácil de medir", "Lo que mide la competencia", "Nada en particular"], "a": 0, "e": "Si no cambia ninguna decisión, sobra."}, {"q": "La ficha técnica de un KPI incluye…", "o": ["Definición, fórmula, fuente, frecuencia, responsable y meta", "Solo el nombre", "Solo el gráfico", "El color del tablero"], "a": 0, "e": "Evita que cada uno lo calcule distinto."}, {"q": "Un tablero bien diseñado…", "o": ["Se entiende en segundos y muestra pocos indicadores clave con su meta", "Tiene todos los datos posibles", "Usa gráficos 3D", "No muestra metas"], "a": 0, "e": "Menos es más."}, {"q": "Indicador de resultado vs. de proceso:", "o": ["El de resultado mide lo logrado; el de proceso, lo que lo genera y permite anticiparse", "Son lo mismo", "El de proceso siempre es financiero", "El de resultado siempre es diario"], "a": 0, "e": "Los de proceso son los que se pueden gestionar día a día."}, {"q": "Ante una variación en un indicador conviene…", "o": ["Distinguir si es variación normal o una señal real antes de reaccionar", "Reaccionar siempre", "Ignorarlas todas", "Cambiar la meta"], "a": 0, "e": "Reaccionar al ruido empeora el proceso."}, {"q": "Una reunión de seguimiento efectiva…", "o": ["Revisa indicadores contra meta, analiza desvíos y define acciones con responsables", "Lee todos los datos en voz alta", "No tiene agenda", "Busca culpables"], "a": 0, "e": "Termina en acciones, no en explicaciones."}]$j$::jsonb);
